<?php require_once "includes/db.php"; $page_title="هۆتێلەکان"; include "includes/header.php";
$stmt=$conn->prepare("SELECT * FROM properties WHERE type=? ORDER BY id DESC");$stmt->execute(["hotel"]);$items=$stmt->fetchAll(PDO::FETCH_ASSOC); ?>
<section class="section"><div class="container"><h1 class="section-title">هۆتێلەکان</h1><div class="cards"><?php foreach($items as $p): ?><div class="card"><img src="<?= htmlspecialchars($p["image"]) ?>"><div class="card-content"><h3><?= htmlspecialchars($p["name"]) ?></h3><p>📍 <?= htmlspecialchars($p["location"]) ?></p><p class="price">$<?= number_format($p["price"],2) ?> / شەو</p><a class="btn" href="details.php?id=<?= $p["id"] ?>">وردەکاری</a></div></div><?php endforeach; ?></div></div></section><?php include "includes/footer.php"; ?>